describe('list_sessions', () => {
  it('answers list_sessions with a session_list when enabled and supported', async () => {
    // A client sends {type: 'list_sessions', limit?, before?} and receives {type: 'session_list', sessions} ([validated by](src/transport/ws/messageHandler.test.ts#L821))
    const sessionStore = {listFor: jest.fn(async () => [])} as unknown as SessionStore;
    const h = harness([], {sessionStore, options: {history: {enabled: true}}});

    await h.send({type: 'list_sessions'});

    expect({
      sent: h.sent,
      listCalledWith: (sessionStore.listFor as jest.Mock).mock.calls[0],
    }).toEqual({
      sent: [{type: 'session_list', sessions: []}],
      listCalledWith: ['u1', {}],
    });
  });

  it('answers UNSUPPORTED when history is not enabled', async () => {
    // When conversation history is not enabled via transport.history.enabled, the server answers list_sessions with an error frame carrying code UNSUPPORTED ([validated by](src/transport/ws/messageHandler.test.ts#L836))
    const h = harness([], {options: {history: {enabled: false}}});
    await h.send({type: 'list_sessions'});
    expect(h.sent).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
  });

  it('answers UNSUPPORTED when the store does not support listFor', async () => {
    // A store without listFor or one that throws StoreCannotList is answered with the same UNSUPPORTED error ([validated by](src/transport/ws/messageHandler.test.ts#L843))
    const h = harness([], {sessionStore: {} as unknown as SessionStore, options: {history: {enabled: true}}});
    await h.send({type: 'list_sessions'});
    expect(h.sent).toEqual([{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]);
  });
});

